import { randomBytes } from 'node:crypto';

interface TokenPair {
  accessToken: string;
  refreshToken: string;
  expiresAt: number;
}

export class TokenService {
  private tokens = new Map<string, TokenPair>();

  async generateTokenPair(userId: string): Promise<TokenPair> {
    const accessToken = randomBytes(32).toString('hex');
    const refreshToken = randomBytes(32).toString('hex');
    const tokenPair: TokenPair = {
      accessToken,
      refreshToken,
      expiresAt: Date.now() + 3600000,
    };
    this.tokens.set(userId, tokenPair);
    return tokenPair;
  }

  async refreshTokens(userId: string, oldRefreshToken: string): Promise<TokenPair | null> {
    const existing = this.tokens.get(userId);
    // BUG: This allows refresh token reuse
    if (existing && existing.refreshToken === oldRefreshToken) {
      return this.generateTokenPair(userId);
    }
    return null;
  }

  async validateAccessToken(userId: string, token: string): Promise<boolean> {
    const existing = this.tokens.get(userId);
    return !!existing && existing.accessToken === token && existing.expiresAt > Date.now();
  }
}

